// CoreActions returns a copy of the route table for the guard tests.
func CoreActions() map[RouteKey]CoreAction {
	return maps.Clone(coreActions)
}

// CoreActionPrefixes are the path prefixes of the portal routers whose
// writing routes the table must classify.
func CoreActionPrefixes() []string {
	return []string{"/api/", "/auth/", "/parent/", "/school/", "/demo/"}
}

// CoreActionExcludedPrefixes are routes under those prefixes that do not
// belong to a portal: the kiosk and CalDAV clients.
func CoreActionExcludedPrefixes() []string {
	return []string{"/api/iot/", "/api/caldav"}
}

func coreActionFor(method, pattern string) (CoreAction, bool) {
	for _, candidate := range normalizePattern(pattern) {
		if action, ok := coreActions[RouteKey{Method: method, Pattern: candidate}]; ok {
			return action, true
		}
	}
	return CoreAction{}, false
}

// coreActionMethods are the methods with at least one captured route; the
// middleware leaves every other request alone.
func coreActionMethods() map[string]bool {
	methods := map[string]bool{}
	for key, action := range coreActions {
		if action.Event != "" {
			methods[key.Method] = true
		}
	}
	return methods
}
